diff --git a/bin/fah_dap_scoped.dart b/bin/fah_dap_scoped.dart
index 30b947ed81..6bf72ede07 100644
--- a/bin/fah_dap_scoped.dart
+++ b/bin/fah_dap_scoped.dart
@@ -256,6 +256,27 @@ final class DapScopedMemberships {
       ...await _loadSession(),
       ..._loadEnv(),
     ];
+    // AC8/AC14 register-time contract: a plaintext key that just entered
+    // memory through this load is registered BEFORE union() returns, so
+    // EVERY consumer (`publicChannelFor`, `privateChannelKeyMissing`,
+    // `preferredBootMembership`, `seedOverlay`, `runtimeEffective`) is
+    // covered. The previous registration points (`_runtimeSecret` via
+    // seedOverlay/runtimeEffective) ride the unawaited boot connect, so
+    // a direct union read raced the boot and could surface an unmasked
+    // plaintext key (gh-219 CI-red). `dapkey1.` envelopes are not secret
+    // material in memory — they register after decryption instead.
+    for (final m in all) {
+      final priv = m.priv;
+      if (priv != null && priv.isNotEmpty && !isEncryptedChannelPriv(priv)) {
+        onSecret?.call(priv);
+      }
+      final clientSecret = [REDACTED:Sensitive-Value];
+      if (clientSecret != null &&
+          clientSecret.isNotEmpty &&
+          !isEncryptedChannelPriv(clientSecret)) {
+        onSecret?.call(clientSecret);
+      }
+    }
     return _union = DapMembershipUnion(all);
   }

diff --git a/test/hub/dap_scoped_memberships_test.dart b/test/hub/dap_scoped_memberships_test.dart
index 3239711614..0f24edae02 100644
--- a/test/hub/dap_scoped_memberships_test.dart
+++ b/test/hub/dap_scoped_memberships_test.dart
@@ -114,6 +114,53 @@ void main() {
     expect(jsonDecode(overlayRaw)['team']['priv'], priv);
   });

+  test('AC8/AC14: union() registers every plaintext priv it loads with '
+      'onSecret — masked before ANY caller can surface it (gh-219 '
+      'CI-red regression)', () async {
+    // The pure-env / imported record shape: a PLAINTEXT priv riding a
+    // session record. union() puts it into memory; registration must be
+    // complete by the time the await resolves.
+    sessionRecords.add({
+      'hubUrl': hub,
+      'channelId': 'runtime',
+      'scope': 'session',
+      'joinedAt': DateTime.now().toUtc().toIso8601String(),
+      'pub': pub,
+      'priv': priv,
+    });
+    final seen = <String>[];
+    final s = DapScopedMemberships(
+      globalConfigFile: globalConfig,
+      globalChannelsFile: globalChannels,
+      overlayChannelsFile: overlay,
+      projectFile: projectFile,
+      environment: const {},
+      appendSessionRecord: (type, data) async {
+        sessionRecords.add(Map<String, Object?>.from(data));
+      },
+      readSessionRecords: (type) async => sessionRecords,
+      keychain: keychain,
+      onSecret: seen.add,
+    );
+
+    // The previous registration points (seedOverlay / runtimeEffective)
+    // ride the unawaited boot connect, so `publicChannelFor` — which
+    // reads the union DIRECTLY — raced them on a loaded CI runner and
+    // lost (gh-219). The load seam itself must register.
+    final effective = await s.union().then((u) => u.effective());
+    expect(effective.map((m) => m.channelId), contains('runtime'));
+    expect(seen, contains(priv));
+
+    // An at-rest envelope is NOT secret material in memory: the load
+    // must not register envelope bytes — only the decrypted plaintext
+    // is (that still happens in _runtimeSecret at runtime resolution).
+    seen.clear();
+    sessionRecords[0]['priv'] = await encryptChannelPriv(priv, pass);
+    s.invalidateCache();
+    await s.union();
+    expect(seen, isEmpty, reason: 'envelope bytes are never registered');
+  });
+
   test('AC2: project scope is invisible from a sibling folder; session '
       'scope is invisible to a second CLI (different records)', () async {
     final env = {'DAP_KEY_PASSPHRASE': pass};

/// Scoped DAP channel membership service (issue #1825): the union of
/// session / project / global / env stores, per-scope join & leave, the
/// passphrase→Keychain resolution chain, and the runtime overlay that
/// feeds the vendored hub client without touching its package.
///
/// Lives in `bin/` (dart:io): file stores and the macOS `security` CLI.
/// The pure algebra (records, union, parser, envelope) is in
/// `lib/src/hub/`.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:math';

import 'package:crypto/crypto.dart';
import 'package:fa_hub_client/fa_hub_client.dart' as client;
import 'package:flutter_agent_harness/src/hub/dap_env_channels.dart';
import 'package:flutter_agent_harness/src/hub/dap_invite_import.dart';
import 'package:flutter_agent_harness/src/hub/dap_key_envelope.dart';
import 'package:flutter_agent_harness/src/hub/dap_membership.dart';
import 'package:flutter_agent_harness/src/plugins/plugin.dart'
    show PluginAppendSessionRecord, PluginReadSessionRecords;

/// The session custom-record type for session-scoped membership. Join
/// records carry the membership payload; leave records add `op: leave`
/// (the session tree is append-only — a leave is a tombstone).
